{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "Eliglustat PBPK simulation gave an absolute oral bioavailability of 8.6%, well below the 20% threshold; despite being a simulation, its high transfer score supports low bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Pravastatin mean oral bioavailability is approximately 18% in humans, below 20%; high transfer supports low, although pravastatin is structurally distinct.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Hexarelin oral bioavailability was 0.3% in humans, far below 20%; high transfer supports low, though it is a peptide.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Laninamivir octanoate, a long-chain ester prodrug, has only 15% oral bioavailability in humans; this is structurally relevant to the query's lipophilic ester/lactone and supports low.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "DVAS, a dodecyl ester dipeptide, showed about 60% oral bioavailability in healthy volunteers; this is the closest structural analogue with high F, but its moderate transfer and the query's non-absorbed lipase-inhibitor design limit its weight.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C33"],
      "claim": "Chloramphenicol palmitate, a long-chain fatty ester prodrug, had 85% oral bioavailability in children, but its very low transfer score makes it a weak contradictory signal.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is orlistat, a highly lipophilic N-formyl-leucine ester of a beta-lactone designed as a non-absorbed GI lipase inhibitor; its absolute oral bioavailability is negligible (<2%). High-transfer experimental analogues (eliglustat, pravastatin, hexarelin, laninamivir octanoate) all show F <20%, supporting low. The few high-F analogues have low-to-moderate transfer and do not represent this non-absorbed class. Therefore predict low.",
  "evidence_gaps": [
    "No direct orlistat bioavailability record is present in the supplied evidence; the conclusion relies on transferable analogues and known pharmacology.",
    "The highest-transfer low-F record (eliglustat) is a PBPK simulation, not direct human experimental data.",
    "Physicochemical solubility/dissolution of the query was not experimentally measured; high logP and low solubility may further limit absorption."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

